package com.zenitrade.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long expiry; public JwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-expiration-ms}") long expiry){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiry=expiry;} public String create(Long id,String email){return Jwts.builder().subject(email).claim("uid",id).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiry)).signWith(key).compact();} public Long userId(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().get("uid",Long.class);} }
